# -*- coding: utf-8 -*-
"""France / Physique-chimie et SVT : 5e（cycle 4）"""
from fr_sci import H, nq, num


def f_sol(R):
    k = R.choice(["c", "c", "m", "V", "sat"])
    if k == "c":
        m, V = R.choice([(10, 0.5), (20, 0.25), (6, 0.2), (30, 1.5), (5, 0.1), (18, 0.6), (45, 1.5), (12, 0.4)])
        return nq("On dissout %s g de sucre dans de l’eau pour obtenir %s L de solution. Quelle est la concentration en masse ?" % (num(m), num(V)), m / V,
                  [m * V, V / m, m / V / 1000], "g/L", "C = m : V = %s g : %s L = %s g/L." % (num(m), num(V), num(m / V)))
    if k == "m":
        c, V = R.choice([(20, 0.5), (50, 0.2), (8, 1.5), (100, 0.25), (35, 2), (12, 0.75)])
        return nq("Une solution a une concentration de %s g/L. Quelle masse de soluté contiennent %s L ?" % (num(c), num(V)), c * V,
                  [c / V, V / c, c + V], "g", "m = C × V = %s × %s = %s g." % (num(c), num(V), num(c * V)))
    if k == "V":
        c, m = R.choice([(20, 10), (50, 5), (100, 25), (8, 4), (30, 60), (40, 10)])
        return nq("On veut %s g de sel avec une solution à %s g/L. Quel volume faut-il prendre ?" % (num(m), num(c)), m / c,
                  [m * c, c / m, m / c * 1000], "L", "V = m : C = %s : %s = %s L." % (num(m), num(c), num(m / c)))
    s, V = R.choice([(360, 0.5), (360, 0.25), (2000, 0.1), (360, 2), (2000, 0.5)])
    n = "sel" if s == 360 else "sucre"
    return nq("La solubilité du %s dans l’eau est d’environ %s g/L. Quelle masse maximale peut-on dissoudre dans %s L ?" % (n, num(s), num(V)), s * V,
              [s / V, s, s * V * 10], "g", "%s g/L × %s L = %s g. Au-delà, la solution est saturée." % (num(s), num(V), num(s * V)))


def f_vit(R):
    k = R.choice(["v", "v", "ms", "d", "t", "kmh"])
    if k == "v":
        d, t = R.choice([(100, 20), (400, 80), (60, 12), (1500, 300), (42, 6), (200, 25), (90, 9)])
        return nq("Un coureur parcourt %s m en %s s. Quelle est sa vitesse moyenne ?" % (num(d), num(t)), d / t, [d * t, t / d, d - t], "m/s", "v = d : t = %s : %s = %s m/s." % (num(d), num(t), num(d / t)))
    if k == "ms":
        v = R.choice([36, 72, 18, 90, 108, 54])
        return nq("Convertis %s km/h en m/s." % num(v), v / 3.6, [v * 3.6, v / 60, v * 1000], "m/s", "%s km/h : 3,6 = %s m/s." % (num(v), num(v / 3.6)))
    if k == "kmh":
        v = R.choice([10, 20, 5, 25, 15, 30])
        return nq("Convertis %s m/s en km/h." % num(v), v * 3.6, [v / 3.6, v * 60, v * 100], "km/h", "%s m/s × 3,6 = %s km/h." % (num(v), num(v * 3.6)))
    if k == "d":
        v, t = R.choice([(13, 30), (90, 2), (340, 3), (25, 8), (60, 1.5), (1.5, 120)])
        u, ut = ("km", "h") if v in (90, 60) else ("m", "s")
        return nq("Un mobile se déplace à %s %s/%s pendant %s %s. Quelle distance parcourt-il ?" % (num(v), u, ut, num(t), ut), v * t, [v / t, v + t, t / v], u,
                  "d = v × t = %s × %s = %s %s." % (num(v), num(t), num(v * t), u))
    d, v = R.choice([(300, 100), (150, 50), (800, 4), (1000, 5), (270, 90), (60, 1.5)])
    u, ut = ("km", "h") if d in (300, 150, 270) else ("m", "s")
    return nq("Quelle durée faut-il pour parcourir %s %s à %s %s/%s ?" % (num(d), u, num(v), u, ut), d / v, [d * v, v / d, d - v], ut, "t = d : v = %s : %s = %s %s." % (num(d), num(v), num(d / v), ut))


